class X2013 { private val m=HashMap<Pair<Int,Int>,Int>();fun add(p:IntArray){val k=p[0] to p[1];m[k]=(m[k]?:0)+1};fun count(p:IntArray):Int{var r=0;for((q,n)in m)if(q.second==p[1]&&q.first!=p[0]){val d=abs(q.first-p[0]);r+=n*(m[p[0] to (p[1]+d)]?:0)*(m[q.first to (p[1]+d)]?:0);r+=n*(m[p[0] to (p[1]-d)]?:0)*(m[q.first to (p[1]-d)]?:0)};return r} }
class X191 { fun hammingWeight(n:Int):Int=n.countOneBits() }
class X268 { fun missingNumber(a:IntArray):Int {var x=a.size;for(i in a.indices)x=x xor i xor a[i];return x} }
class X7 {
    fun reverse(x: Int): Int {
        var n = x
        var result = 0L
        while (n != 0) { result = result * 10 + n % 10; n /= 10 }
        return if (result < Int.MIN_VALUE.toLong() || result > Int.MAX_VALUE.toLong()) 0 else result.toInt()
    }
}
